import math

def discrete(u0, k, steps, dt=1):
    u = u0
    for _ in range(steps):
        u *= (1 + k*dt)  # approximation d'Euler
    return u

def continuous(u0, k, t):
    return u0 * math.exp(k * t)

print(f"Discrète (dt=1) après 10: {discrete(100, 0.1, 10):.2f}")
print(f"Continue après 10: {continuous(100, 0.1, 10):.2f}")
print(f"Discrète (dt=0.1) après 10: {discrete(100, 0.1, 100, 0.1):.2f}")
